    const swap = await executeSwap(quote.quote_id);
    await waitForSwap(swap.swap_id);
  }

  // Step 6: Execute buys (USDC → underweight)
  for (const b of buys) {
    if (b.symbol === "USDC") continue;
    console.log(`  Swapping ~$${b.usd.toFixed(2)} USDC → ${b.symbol}...`);
